using System.Reflection;
using UnityEngine;
using JojoP.Gameplay.Brothers;
public static class McpSkipWave {
  public static string Run() {
    Time.timeScale = 1f;
    var s = Object.FindFirstObjectByType<BrothersSessionController>();
    if (s == null) return "no session";
    var b = s.Battle;
    if (b == null) return "flow=" + s.Flow + " no battle";
    var f = typeof(BrothersBattleController).GetField("_waveLeft", BindingFlags.NonPublic | BindingFlags.Instance);
    f?.SetValue(b, 0f);
    var end = typeof(BrothersBattleController).GetMethod("EndWaveCleared", BindingFlags.NonPublic | BindingFlags.Instance);
    end?.Invoke(b, null);
    return "flow=" + s.Flow + " left=" + b.WaveLeft;
  }
}
